const ALL = { en, es, tr, ka, pt, de, ru } as const;

export function draftCopy(locale: string) {
  const key = (locale in ALL ? locale : "en") as keyof typeof ALL;
  const base = ALL[key];
  return { ...base, lineNames: LINE_NAMES[key] };
}
export type DraftText = ReturnType<typeof draftCopy>;
